"""Core engine components.

This module demonstrates nested classes, decorated functions and a
private helper that must be skipped by the documentation generator.
"""

from functools import lru_cache


class BaseEngine:
    """Abstract base class for all engines."""

    def describe(self) -> str:
        """Return a human readable description of the engine."""


class Engine(BaseEngine):
    """A piston engine that can be started and stopped.

    Example::

        engine = Engine(cylinders=6)
        assert engine.start() is True
        engine.stop()
    """

    class Spec:
        """Specification of a single engine."""

        def capacity(self) -> float:
            """Return the total capacity in litres."""
            return 2.0

    def __init__(self, cylinders: int = 4, fuel: str = "gasoline") -> None:
        self.cylinders = cylinders
        self.fuel = fuel

    def start(self) -> bool:
        """Start the engine and return ``True`` on success."""
        return True

    def stop(self) -> None:
        """Stop the engine."""
        pass

    def _prime_fuel_pump(self) -> None:
        """Internal helper; must never appear in generated docs."""
        pass


def log_calls(func):
    """Decorator that pretends to log every call to *func*."""

    def wrapper(*args, **kwargs):
        print(f"calling {func.__name__}")
        return func(*args, **kwargs)

    return wrapper


@log_calls
def ignite(fuel: str, times: int = 1) -> str:
    """Ignite the given fuel one or more times.

    The decorator above proves that decorated functions are documented.
    """
    return f"ignited {fuel} x{times}"


@lru_cache(maxsize=None)
def cached_factorial(n: int) -> int:
    """Return ``n!`` memoized through :func:`functools.lru_cache`."""
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

